-- UNREGISTERED candidate. Fixed cfc derivation evidence is NOT a signature.
-- Dependencies: finance-budget-mixed-source.sql, social-operating-custody.sql and
-- the official 0009 canonical JSON codec.
-- No new role, membership, policy, login, authority, credential or base-table
-- permission. SQL never parses the full seed JSON. Only exact version-pinned
-- <=512KiB derived country input is parsed; existing online outputs stay bounded.
-- Apply only through the companion's reviewed immutable-source release chain.
begin;
create function world_v2.verify_postwar_finance_social_publication(p_text text,p_kind text)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare effective name;required name;d jsonb;a world_v2.runtime_opening_admission%rowtype;q world_v2.runtime_admission_publication_permit%rowtype;s record;pins jsonb;h record;
begin
 effective:=case when current_setting('role')='none'then session_user else current_setting('role')::name end;
 required:=case p_kind when 'FINANCE'then 'world_v2_finance_budget_source_publisher'when 'SOCIAL'then 'world_v2_social_source_publisher'else null end;
 if required is null or not pg_has_role(effective,required,'MEMBER')or pg_has_role(effective,case p_kind when 'FINANCE'then 'world_v2_social_source_publisher'else 'world_v2_finance_budget_source_publisher'end,'MEMBER')or exists(select 1 from pg_roles r where r.rolname=effective and(r.rolsuper or r.rolbypassrls or r.rolcreatedb or r.rolcreaterole or r.rolreplication))or exists(select 1 from pg_roles r where r.rolname in('world_v2_finance_budget_source_owner','world_v2_social_source_owner','world_v2_finance_budget_source_reader','world_v2_social_source_reader')and pg_has_role(effective,r.oid,'MEMBER'))then raise exception 'FIXED_FINANCE_SOCIAL_PUBLISHER_REQUIRED'using errcode='42501';end if;
 if p_text is null or octet_length(p_text)>524288 then raise exception 'BOUNDED_DERIVED_COUNTRY_REQUIRED'using errcode='22023';end if;
 d:=p_text::jsonb;
 -- Generated from the retained genuine cfc seed by the fixed Core/E03 producer.
 -- Retained: config/postwar-genesis/finance-social-source-manifest.v1.json
 -- Canonical manifest SHA256: 4944efb3b58fad30e7456a1b391d6b34f1cd0090c91599ab513ba590b863747b
 -- Review must retain manifest bytes alongside this immutable proposal.
 pins:='{"COUNTRY_01":"60a0b61221cb7409235ab79d3bfc9f463fdc756ee1548ac6717b20cf0e33982b","COUNTRY_02":"62bb67db26bb335ef39ce8678a8b5e225472095bfc7f773e467ba78944c47c8a","COUNTRY_03":"a7aa39c5b182aa739fa07b19590d428aa96b90f509421d0b766f7710b9b0a4df","COUNTRY_04":"aa8ad599d6b5a64d80e2842d879d24f7b034e28fb17f56e20b5d74768c070840","COUNTRY_05":"cc30818aab43c8b279cd4604dae09cfe9cc609be62fafbdb3e10d7c022d7d683","COUNTRY_06":"1cd4e1077a11ca3ba690d5f8751c955375e4e2ec4b8bd6fef1a9cfba67ee12e3","COUNTRY_07":"76b7143dc13bba7f0b60e90d801124d4da91b8b67ac26aefc5d08b47be3a0fe8","COUNTRY_08":"ef1bde7d4d31643655a7a2a5b61b6a3cd9305b81c6afa7a9b491bc9137baff4a","COUNTRY_09":"c919a5a363eaf2754716a54ee289b301d2f464f9a94e109aafef3f5f5e504464","COUNTRY_10":"ce9541987f00814025a6ce4549684c19389b8d00fea8c6ddddfd38c4a996a4c4","COUNTRY_11":"8dc3f79aeb7af85a8c139ffa8a35ef73633fc299ada75189ad60fb136cdaa183","COUNTRY_12":"f9bfa3066726afdec55b5aa50dd26de93a33118c03aaf353112b68986649ef2e","COUNTRY_13":"e8455491535da28bbd192f4638ecd8b5c5f725fad4d21c2e631223b28d06292e","COUNTRY_14":"63bd488722d9a1da0f09cb89335faad30c67af0c3f5c08372f57fe4378a2245a","COUNTRY_15":"657a8871e69820d58d85f94413f23d871808f57b1e94b02cf7f46b767e8daa0f","COUNTRY_16":"e118a688d5f08bc14e0394d45f5326bdb97234c5c5e213e04e5139df8e5bbb8e","COUNTRY_17":"4414cae96b4a63933b96f78695ac51c0a001b9f15f7c4010f2601732483559a4","COUNTRY_18":"e72564a9581b96c1b9da3e727ef772b692fc644197c6f5be0f45eb598c31169c","COUNTRY_19":"387fcbb060f46257af1e9330b178ed9e1a3471997e02809fc81cf972c94d562b","COUNTRY_20":"bcda7aac9b0fd9330e1fdd016ede40de78887e869d21d4bf53accf8a3485bb75","COUNTRY_21":"0d61816b9d3e840a96d108d6512ae2a3ebc51e77a21ef4af4f4a441766f11589","COUNTRY_22":"8b1196148d46f076b6861589a4e387e28fc7c7015a81137fd6edcbad44ad11ef","COUNTRY_23":"aa0d21f8ad2f94641067ca84305654356014b3b6869360fa0a38fd21ee41a49e","COUNTRY_24":"9f0fffa17115cb4d579cd7fdc4d4b2a6e411cb96025edac80d63bc06371e731f","COUNTRY_25":"584b2f6ca385a9c4fb05fdfde0df0bf2881e8f93a19adb7c404584008