 if d->>'schemaVersion'is distinct from 'postwar-finance-social-country-original-v1'or d->>'worldId'is distinct from 'WORLD_POSTWAR_GCU_OPENING_20261029_V1'or d->>'seedId'is distinct from 'SEED_POSTWAR_GCU_OPENING_20261029_V1'or d->>'seedFingerprint'is distinct from 'sha256:cfc55796562b44bd616f33082cbbafd9dbd43d58733a24ac550339cbc8376274'or d->>'canonicalSeedSha256'is distinct from '75649466e384c0616ee84cdfbfa7636fa0bae09438e30a19ef69138059093e2f'or pins->>(d->>'countryId')is null or pins->>(d->>'countryId')is distinct from encode(sha256(convert_to(p_text,'UTF8')),'hex')then raise exception 'FIXED_CORE_DERIVATION_HASH_REQUIRED'using errcode='23514';end if;
 perform set_config('econmind.finance_budget_source_world',d->>'worldId',true);
 select world_version,event_sequence into strict h from world_v2.world_head where world_id=d->>'worldId'for share;
 select world_id,seed_id,seed_fingerprint,replay_binding,opening_world_version,encode(sha256(convert_to(canonical_payload,'UTF8')),'hex')as raw_sha into strict s from world_v2.opening_seed where world_id=d->>'worldId';
 if s.seed_id<>d->>'seedId'or s.seed_fingerprint<>d->>'seedFingerprint'or s.raw_sha<>d->>'canonicalSeedSha256'or s.opening_world_version<>0 then raise exception 'ACTUAL_STORED_SEED_HASH_REQUIRED'using errcode='23514';end if;
 select * into strict a from world_v2.runtime_opening_admission where world_id=s.world_id and seed_id=s.seed_id and seed_fingerprint=s.seed_fingerprint and replay_binding=s.replay_binding;
 select * into q from world_v2.runtime_admission_publication_permit p where 'ADMISSION_'||upper(p.authorization_sha256)=a.admission_ref and p.world_id=a.world_id and p.seed_id=a.seed_id and p.seed_fingerprint=a.seed_fingerprint and p.model_version=a.model_version and p.replay_binding=a.replay_binding and a.admitted_at_real>=p.valid_from and a.admitted_at_real<p.valid_until for share;
 if not found or exists(select 1 from world_v2.runtime_admission_publication_revocation r where r.authorization_id=q.authorization_id)then raise exception 'ACTUAL_SIGNED_ADMISSION_REQUIRED'using errcode='55000';end if;
 return jsonb_build_object('original',d,'admissionRef',a.admission_ref,'sourceBundleSha256',q.source_bundle_sha256,'observedHead',jsonb_build_object('worldVersion',h.world_version::text,'eventSequence',h.event_sequence::text));
end;$$;
alter function world_v2.verify_postwar_finance_social_publication(text,text)owner to world_v2_finance_budget_source_owner;
revoke all on function world_v2.verify_postwar_finance_social_publication(text,text)from public;
grant execute on function world_v2.verify_postwar_finance_social_publication(text,text)to world_v2_social_source_owner;

create function world_v2.publish_postwar_social_source_bounded(p_text text)
returns table(source_ref text,source_sha256 text)language plpgsql security definer set search_path=pg_catalog as $$
declare b jsonb;d jsonb;r world_v2.social_operating_source_registration%rowtype;ref text;
begin
 b:=world_v2.verify_postwar_finance_social_publication(p_text,'SOCIAL');d:=b->'original';
 perform set_config('econmind.social_custody_world',d->>'worldId',true);
 ref:='SOCIAL_REG_'||upper(encode(sha256(convert_to(jsonb_build_array(d->>'worldId',d->>'countryId',d->>'seedFingerprint',d->>'operatingSourceId')::text,'UTF8')),'hex'));
 insert into world_v2.social_operating_source_registration(world_id,country_id,registration_ref,seed_fingerprint,source_id,source_payload_hash,admission_ref,issuer_role)values(d->>'worldId',d->>'countryId',ref,d->>'seedFingerprint',d->>'operatingSourceId',d->>'operatingSourcePayloadHash',b->>'admissionRef','world_v2_social_source_publisher')on conflict(world_id,country_id)do nothing;
 select * into strict r from world_v2.social_operating_source_registration where world_id=d->>'worldId'and country_id=d->>'countryId'for share;
 if r.registration_ref<>ref or r.seed_fingerprint<>d->>'seedFingerprint'or r.source_id<>d->>'operatingSourceId'or r.source_payload_hash<>d->>'operatingSourcePayloadHash'or r.admission_ref<>b->>'admissionRef'then raise exception 'SOCIAL_IMMUTABLE_ORIGINAL_CONFLICT'using errcode='23514';end if;
 if exists(select 1 from world_v2.social_operating_source_revocation x where x.registration_ref=ref)then raise exception 'SOCIAL_SOURCE_REVOKED'using errcode='55000';end if;
 return query select r.registration_ref,r.source_payload_hash;
end;$$;
alter function world_v2.publish_postwar_social_source_bounded(text)owner to world_v2_social_source_owner;
revoke all on function world_v2.publish_postwar_social_source_bounded(text)from public;
grant execute on function world_v2.publish_postwar_social_source_bounded(text)to world_v2_social_source_publisher;

create function world_v2.publish_postwar_finance_source_bounded(p_text text)
returns table(source_ref text,source_sha256 text)language plpgsql security definer set search_path=pg_catalog as $$
declare b jsonb;d jsonb;scope_text text;scope_hash text;body jsonb;bytes text;hash text;ref text;old world_v2.finance_budget_mixed_social_original%rowtype;c world_v2.finance_budget_capacity_original%rowtype;
begin
 b:=world_v2.verify_postwar_finance_social_publication(p_text,'FINANCE');d:=b->'original';
 -- Canonical bytes use the shared fixed JSON codec, not JSONB display spacing.
 scope_text:=world_v2.canonical_json(d->'scope');scope_hash:=encode(sha256(convert_to(scope_text,'UTF8')),'hex');
 body:=jsonb_build_object('schemaVersion','finance-budget-mixed-social-source-v1','worldId',d->>'worldId','countryId',d->>'countryId','seedId',d->>'seedId','seedFingerprint',d->>'seedFingerprint','admissionRef',b->>'admissionRef','canonicalSeedSha256','sha256:'||(d->>'canonicalSeedSha256'),'sourceBundleSha256',b->>'sourceBundleSha256','operatingSourceId',d->>'operatingSourceId','operatingSourcePayloadHash',d->>'operatingSourcePayloadHash','state',d->'state','offers',d->'offers','fundingAccounts',d->'fundingAccounts','scopeSha256',scope_hash);
 bytes:=world_v2.canonical_json(body);hash:=encode(sha256(convert_to(bytes,'UTF8')),'hex');ref:='BUDGET_MIXED_SOCIAL_'||upper(encode(sha256(convert_to((d->>'seedFingerprint')||chr(10)||(d->>'countryId'),'UTF8')),'hex'));
 if octet_length(bytes)>262144 or octet_length(scope_text)>262144 then raise exception 'BOUNDED_MIXED_SOURCE_REQUIRED'using errcode='54000';end if;
 insert into world_v2.finance_budget_mixed_social_original values(d->>'worldId',d->>'countryId',ref,d->>'seedFingerprint',b->>'admissionRef',d->>'canonicalSeedSha256',bytes,hash,scope_text,scope_hash)on conflict(world_id,country_id)do nothing;
 select * into strict old from world_v2.finance_budget_mixed_social_original where world_id=d->>'worldId'and country_id=d->>'countryId'for share;
 if old.source_ref<>ref or old.source_sha256<>hash or old.source_text<>bytes or old.scope_document<>scope_text or old.scope_sha256<>scope_hash or old.seed_fingerprint<>d->>'seedFingerprint'or old.admission_ref<>b->>'admissionRef'or old.canonical_seed_sha256<>d->>'canonicalSeedSha256'then raise exception 'FINANCE_IMMUTABLE_MIXED_CONFLICT'using errcode='23514';end if;
 body:=(d->'capacity')||jsonb_build_object('admissionRef',b->>'admissionRef');bytes:=world_v2.canonical_json(body);hash:=encode(sha256(convert_to(bytes,'UTF8')),'hex');ref:='BUDGET_CAPACITY_SOURCE_'||upper(encode(sha256(convert_to((d->>'seedFingerprint')||chr(10)||(d->>'countryId'),'UTF8')),'hex'));
 if octet_length(bytes)>65536 then raise exception 'BOUNDED_CAPACITY_SOURCE_REQUIRED'using errcode='54000';end if;
 insert into world_v2.finance_budget_capacity_original values(d->>'worldId',d->>'countryId',ref,d->>'seedFingerprint',b->>'admissionRef',d->>'canonicalSeedSha256',bytes,hash)on conflict(world_id,country_id)do nothing;
 select * into strict c from world_v2.finance_budget_capacity_original where world_id=d->>'worldId'and country_id=d->>'countryId'for share;
 if c.capacity_ref<>ref or c.source_sha256<>hash or c.source_text<>bytes or c.seed_fingerprint<>d->>'seedFingerprint'or c.admission_ref<>b->>'admissionRef'or c.canonical_seed_sha256<>d->>'canonicalSeedSha256'then raise exception 'FINANCE_IMMUTABLE_CAPACITY_CONFLICT'using errcode='23514';end if;
 if exists(select 1 from world_v2.finance_budget_capacity_revocation r where r.capacity_ref=ref)then raise exception 'FINANCE_CAPACITY_REVOKED'using errcode='55000';end if;
 return query select c.capacity_ref,c.source_sha256;
end;$$;
alter function world_v2.publish_postwar_finance_source_bounded(text)owner to world_v2_finance_budget_source_owner;
revoke all on function world_v2.publish_postwar_finance_source_bounded(text)from public;
grant execute on function world_v2.publish_postwar_finance_source_bounded(text)to world_v2_finance_budget_source_publisher;
commit;
